examples.template:
if (open) {
    // While the contacts are deleted, a swipe, back or a tap outside does not close the sheet.
    MonarchBottomSheet(onDismissRequest = { open = false }, dismissible = !running) {
        Column(
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            when {
                finished -> {
                    MonarchBanner(
                        title = "${count - failed.size} of $count $noun deleted",
                        message = if (failed.isEmpty()) "Every contact was deleted." else "Not deleted: ${failed.joinToString()}",
                        tone = if (failed.isEmpty()) MonarchTone.Success else MonarchTone.Warning,
                        announcement = MonarchBannerAnnouncement.Polite,
                    )
                    MonarchButton(
                        text = "Done",
                        onClick = { open = false },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                    )
                }
                running -> MonarchProgress(progress = done / count.toFloat(), label = "$done of $count deleted")
                else -> {
                    MonarchText(text = {{trigger}}, style = MonarchTextStyle.Heading)
                    MonarchText(text = "Check before you delete", style = MonarchTextStyle.Subheading)
                    MonarchText(text = "This cannot be undone.", color = MonarchTheme.colors.textMuted)
                    MonarchText(text = "Selected", style = MonarchTextStyle.Caption)
                    sample.forEach { MonarchText(text = it, style = MonarchTextStyle.BodyStrong) }
                    MonarchText(text = "+${count - sample.size} more", color = MonarchTheme.colors.textMuted)
                    MonarchConsequenceList(
                        items = listOf(
                            MonarchConsequence(MonarchConsequenceKind.{{consequences.0.kind|pascal}}, {{consequences.0.label}}, count = {{consequences.0.count}}),
                            MonarchConsequence(MonarchConsequenceKind.{{consequences.1.kind|pascal}}, {{consequences.1.label}}),
                        ),
                    )
                    MonarchTypeToConfirmInput(
                        phrase = "$count",
                        value = typed,
                        onValueChange = { typed = it },
                        label = "Type $count to confirm",
                    )
                    MonarchButton(
                        text = {{trigger}},
                        onClick = { running = true },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Danger,
                        enabled = MonarchTypeToConfirmInputDefaults.matches(typed, "$count"),
                    )
                    MonarchButton(
                        text = "Cancel",
                        onClick = { open = false },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Ghost,
                    )
                }
            }
        }
    }
}

